import XCTest
@testable import MirNavigation

final class CapturedShopTests:XCTestCase {
    func testRealServerTradeMessages() throws {
        let hexFrames:[String] = [
    "626d636c66456a6a6764686b6464686b4150543f405a41475c584943554341685f603f5f60603f6162603f6b543f57463c5a41435c584943554341685f603f5f60603f6162603f6b543f7658525f59685f61595f5f62585f5f3c",
    "",
    "5864686664466a694049554471646867",
    "4049554471796a656464686b6464686b543f7658523f",
    "4049554471786a656464686b6464686b543f7658523f",
    "7a415c606c466a6a6464686b6464686b",
    "6664686764476a6a6464686b6464686b",
    "5a64686264446a696464686b6464686b"
]
        var seen=Set<UInt16>()
        for hex in hexFrames {
            let chars=Array(hex)
            let raw=stride(from:0,to:chars.count,by:2).map { UInt8(String(chars[$0...$0+1]),radix:16)! }
            let packet=try MirWire.packet(raw);seen.insert(packet.id)
            if packet.id==652 {
                XCTAssertEqual(packet.bodyParts.count,Int(packet.x))
                XCTAssertTrue(packet.bodyParts.allSatisfy{MirEquipment.item($0) != nil})
            }
            if packet.id==647 { XCTAssertGreaterThan(packet.actor,0) }
        }
        XCTAssertTrue(Set<UInt16>([600,645,646,647,648,650,652]).isSubset(of:seen))
    }
}
